import numpy as np
def jl_min_dimension(n_points, epsilon=0.1):
    return int(4 * np.log(n_points) / (epsilon**2 / 2 - epsilon**3 / 3))

print(jl_min_dimension(1_000_000, epsilon=0.1))   # a few thousand, independent of original dimension

import numpy as np
def cosine_sim(u, v):
    return u @ v / (np.linalg.norm(u) * np.linalg.norm(v))

# cosine_sim(a, b) before projection is close to cosine_sim(a_proj, b_proj) after
